def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    # Find rectangular outlines. The large outline determines the fill color:
    # in these puzzles it is 7 for a 7-by-7 outline.
    frames = []
    for color in set(v for row in g for v in row if v != bg):
        cells = [(r, c) for r in range(h) for c in range(w) if g[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1 > r0 and c1 > c0 and all(
            g[r0][c] == color and g[r1][c] == color for c in range(c0, c1 + 1)
        ) and all(g[r][c0] == color and g[r][c1] == color for r in range(r0, r1 + 1)):
            frames.append((r1-r0+1, r0, r1, c0, c1, color))

    if not frames:
        return g
    largest = max(frames, key=lambda x: x[0] * (x[4]-x[3]+1))
    fill = 7 if largest[0] >= 7 else 2

    for _, r0, r1, c0, c1, color in frames:
        # The fill color is associated with each outline by its size.
        local_fill = 7 if (r1-r0+1) >= 7 else fill
        for r in range(r0+1, r1):
            for c in range(c0+1, c1):
                g[r][c] = local_fill
    return g
