    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    frames = []
    for color in set(v for row in g for v in row if v != bg):
        cells = [(r, c) for r in range(h) for c in range(w) if g[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        if r1 <= r0 or c1 <= c0:
            continue
        if (all(g[r0][c] == color and g[r1][c] == color for c in range(c0, c1 + 1))
            and all(g[r][c0] == color and g[r][c1] == color for r in range(r0, r1 + 1))):
            frames.append((r1-r0+1, c1-c0+1, r0, r1, c0, c1))

    for rh, cw, r0, r1, c0, c1 in frames:
        if rh >= 7 or cw >= 7:
            fill = 7
        elif rh == 6 and cw == 6:
            fill = 2
        elif rh == 4 and cw == 4:
            fill = 2
        else:
            fill = 7
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                g[r][c] = fill
    return g
